        rn=int(rm.group(1))
        for c in re.findall(r'<c\b.*?(?=<c\b|</row)', r, re.S):
            rm2=re.search(r'r="([A-Z]+\d+)"', c)
            if rm2:
                out[(rn, rm2.group(1))]=c
    return out
